mapper.select:
SELECT id, user_id, activity_id, strategy_id, order_id, award_id, award_title, award_time,
       award_state, create_time, update_time
FROM user_award_record
WHERE user_id = #{userId}
  AND activity_id = #{activityId}
ORDER BY id DESC

mapper.update:
UPDATE user_award_record
SET award_state = #{awardState},
    update_time = NOW()
WHERE user_id = #{userId}
  AND order_id = #{orderId}

UPDATE user_award_record
SET award_state = #{awardState},
    update_time = NOW()
WHERE user_id = #{userId}
  AND order_id = #{orderId}
  AND award_state = 'create'
